const GDATA = [{"lvl": "A1", "items": [{"t": "Ser vs. Estar", "d": "ser表本质/身份，estar表状态/位置", "ex": "Ella es profesora; está cansada."}, {"t": "Presente de indicativo", "d": "陈述式现在时", "ex": "Yo estudio español cada día."}, {"t": "Artículos definidos", "d": "定冠词el/la/los/las", "ex": "La casa es grande; los libros."}, {"t": "Artículos indefinidos", "d": "不定冠词un/una/unos/unas", "ex": "Un libro; unas manzanas."}, {"t": "Concordancia género/número", "d": "名词-形容词的性与数一致", "ex": "Las casas blancas son grandes."}, {"t": "Pronombres personales", "d": "主语人称代词", "ex": "Nosotros vivimos en Madrid."}, {"t": "Verbos regulares -ar", "d": "-ar结尾规则动词变位", "ex": "Yo hablo, tú hablas, él habla."}, {"t": "Verbos regulares -er/-ir", "d": "-er/-ir结尾规则动词变位", "ex": "Yo como, tú vives, él escribe."}, {"t": "Negación con no", "d": "用no否定", "ex": "No tengo tiempo; no quiero."}, {"t": "Preguntas", "d": "疑问句结构", "ex": "¿Cómo te llamas? ¿Dónde vives?"}]}, {"lvl": "A2", "items": [{"t": "Pretérito perfecto", "d": "短过去时(haber+过去分词)", "ex": "Hoy he comido paella."}, {"t": "Pretérito indefinido", "d": "简单过去时", "ex": "Ayer visité el museo."}, {"t": "Pretérito imperfecto", "d": "过去未完成时", "ex": "Cuando era niño, jugaba en el parque."}, {"t": "Por vs. Para", "d": "por表原因/途径，para表目的", "ex": "Viajo por trabajo; compro para ti."}, {"t": "Futuro simple", "d": "将来时", "ex": "Mañana iré al dentista."}, {"t": "Verbos reflexivos", "d": "代词式动词", "ex": "Me levanto a las siete."}, {"t": "Comparativos", "d": "比较级", "ex": "María es más alta que Juan."}, {"t": "Superlativos", "d": "最高级", "ex": "Es el mejor restaurante de la ciudad."}, {"t": "Gustar y similares", "d": "gustar等动词特殊用法", "ex": "Me gusta el café; me encantan los libros."}, {"t": "Adverbios de frecuencia", "d": "频率副词", "ex": "Siempre desayuno café; nunca como carne."}]}, {"lvl": "B1", "items": [{"t": "Indefinido vs. Imperfecto", "d": "indefinido叙完成，imperfecto描背景", "ex": "Llovía cuando salí de casa."}, {"t": "Imperativo afirmativo", "d": "命令式肯定", "ex": "Estudia más; come verduras."}, {"t": "Imperativo negativo", "d": "命令式否定(no+subj.)", "ex": "No comas tanto; no fumes aquí."}, {"t": "Pronombres objeto directo", "d": "直接宾语代词lo/la", "ex": "Lo compré ayer; la vi en el parque."}, {"t": "Pronombres objeto indirecto", "d": "间接宾语代词le/les", "ex": "Le di el libro; les escribí un correo."}, {"t": "Doble pronombre", "d": "双宾语代词(se lo)", "ex": "Se lo di ayer; me lo dijo."}, {"t": "Subjuntivo presente", "d": "虚拟式现在时", "ex": "Espero que vengas pronto."}, {"t": "Condicional simple", "d": "条件式", "ex": "Sería mejor estudiar más."}, {"t": "Perífrasis verbales", "d": "动词短语tener que/deber", "ex": "Tengo que terminar el trabajo."}, {"t": "Oraciones condicionales reales", "d": "真实条件句", "ex": "Si llueve, no saldremos."}, {"t": "Relativos", "d": "关系代词que/donde", "ex": "La casa donde vivo es grande."}, {"t": "Pronombre se impersonal", "d": "无人称se", "ex": "Se habla español en España."}, {"t": "Pasiva refleja", "d": "被动反射se", "ex": "Se venden pisos aquí."}]}, {"lvl": "B2", "items": [{"t": "Subjuntivo pasado", "d": "虚拟式过去时", "ex": "Me gustaría que vinieras."}, {"t": "Conectores discursivos", "d": "连接词", "ex": "Sin embargo, por consiguiente, asimismo."}, {"t": "Estilo indirecto", "d": "间接引语", "ex": "Dice que ha terminado; preguntó si podía venir."}, {"t": "Estilo indirecto: preguntas", "d": "间接引语转述疑问", "ex": "Preguntó dónde vivía yo."}, {"t": "Estilo indirecto: órdenes", "d": "间接引语转述命令", "ex": "Me dijo que llegara temprano."}, {"t": "Oraciones de relativo (lo que)", "d": "关系从句", "ex": "Lo que quiero es descansar."}, {"t": "Pretérito pluscuamperfecto", "d": "过去完成时", "ex": "Ya había salido cuando llamaste."}, {"t": "Oraciones concesivas", "d": "让步从句(aunque+subj.)", "ex": "Aunque llueva, iré."}, {"t": "Oraciones causales", "d": "原因从句", "ex": "Como llegué tarde, no entré."}, {"t": "Oraciones finales", "d": "目的从句(para que+subj.)", "ex": "Te llamo para que vengas."}, {"t": "Oraciones consecutivas", "d": "结果从句(tan...que)", "ex": "Es tan difícil que no lo entiendo."}, {"t": "Condicionales irreales", "d": "非真实条件句", "ex": "Si tuviera dinero, viajaría."}, {"t": "Subjuntivo en relativas", "d": "虚拟式在关系从句", "ex": "Busco a alguien que hable chino."}, {"t": "Subjuntivo con duda", "d": "虚拟式与怀疑表达", "ex": "Dudo que venga a la fiesta."}, {"t": "Subjuntivo con emoción", "d": "虚拟式与情感表达", "ex": "Me alegra que hayas aprobado."}, {"t": "Concordancia de tiempos", "d": "时态一致", "ex": "Dijo que vendría ayer."}, {"t": "Oraciones adversativas", "d": "转折从句(pero/sino)", "ex": "No es grande, sino pequeño."}, {"t": "Pronombres relativos prep.", "d": "带介词关系代词", "ex": "El amigo con quien hablé es médico."}, {"t": "Usos de se", "d": "se的各种用法", "ex": "Se construyó el puente en un año."}, {"t": "Indefinidos y negativos", "d": "不定代词和否定词", "ex": "Nadie lo sabe; no hay nadie aquí."}, {"t": "Perífrasis de obligación", "d": "义务动词短语", "ex": "Hay que estudiar más para aprobar."}]}];

// Flatten grammar for easier access
const GFLAT = [];
GDATA.forEach(g => g.items.forEach(it => GFLAT.push(Object.assign({lvl:g.lvl}, it))));

